// @vitest-environment jsdom
import React from "react";
import { createRoot, type Root } from "react-dom/client";
import { act } from "react-dom/test-utils";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import SettingItemRow from "~/components/settings/components/SettingItemRow";
import { ROAM_DOCS_ASSETS } from "~/components/settings/utils/docs";
import { PERSONAL_KEYS } from "~/components/settings/utils/settingKeys";

describe("SettingItemRow example", () => {
  let container: HTMLDivElement;
  let root: Root;

  const render = (props: React.ComponentProps<typeof SettingItemRow>): void => {
    act(() => root.render(React.createElement(SettingItemRow, props)));
  };

  beforeEach(() => {
    vi.stubGlobal("IS_REACT_ACT_ENVIRONMENT", true);
    container = document.createElement("div");
    document.body.appendChild(container);
    root = createRoot(container);
  });
  afterEach(() => {
    act(() => root.unmount());
    container.remove();
    vi.unstubAllGlobals();
  });

  it("shows the Overlay example from the docs site, captioned with both badge numbers", () => {
    render({
      label: "Overlay",
      settingKeys: [PERSONAL_KEYS.discourseContextOverlay],
      control: React.createElement("input"),
    });
    const img = container.querySelector("img");
    expect(img?.getAttribute("src")).toBe(
      ROAM_DOCS_ASSETS.discourseContextOverlay,
    );
    expect(img?.getAttribute("alt")).toBeTruthy();
    const caption = container.querySelector("figcaption")?.textContent ?? "";
    expect(caption).toMatch(/discourse relations/);
    expect(caption).toMatch(/reference/);
  });

  it("keeps the caption when the image cannot load", () => {
    render({
      label: "Overlay",
      settingKeys: [PERSONAL_KEYS.discourseContextOverlay],
      control: React.createElement("input"),
    });
    act(() => {
      container.querySelector("img")!.dispatchEvent(new Event("error"));
    });
    expect(container.querySelector("img")).toBeNull();
    expect(container.querySelector("figcaption")).not.toBeNull();
  });

  it("renders no figure for a setting without an example", () => {
    render({
      label: "Plain",
      description: "No example here.",
      settingKeys: ["not-in-catalog"],
      control: React.createElement("input"),
    });
    expect(container.querySelector("figure")).toBeNull();
  });

  it("skips the example on the inline variant", () => {
    render({
      label: "Overlay",
      settingKeys: [PERSONAL_KEYS.discourseContextOverlay],
      control: React.createElement("input"),
      inline: true,
    });
    expect(container.querySelector("figure")).toBeNull();
  });
});

